functions.cancelFallbackClose:
function cancelFallbackClose() {
  fallbackCloseGeneration += 1;
  if (fallbackCloseTimer !== null) clearTimeout(fallbackCloseTimer);
  fallbackCloseTimer = null;
  cancelFallbackCloseButton.hidden = true;
}
window.addEventListener("pagehide", cancelFallbackClose);
cancelFallbackCloseButton.addEventListener("click", () => {
  cancelFallbackClose();
  saveStatus.textContent = "自動で閉じるのを取り消しました。保存完了は未確認です。画面を残します。";
});
const ownedDocument = document;
const ownedRoot = document.documentElement;
let preparedSave = null;
let saveBusy = false;
saveStatus.textContent = "全件取得後、通常ダウンロードを要求して5秒後に閉じます（保存完了は未確認）。待機中は取消できます。";

functions.isOwnedExporter:
function isOwnedExporter() {
  try {
    return window !== qb && window === window.top && window.opener === qb &&
      !!qb && window.location.href === "about:blank" &&
      document === ownedDocument && document.documentElement === ownedRoot;
  } catch (_) { return false; }
}

functions.closeOwnedExporter:
function closeOwnedExporter() {
  if (!isOwnedExporter()) {
    saveStatus.textContent = "取得ツールの画面を確認できないため、この画面は閉じません。";
    return;
  }
  try { window.close(); } catch (_) {}
  saveStatus.textContent = "閉じる操作を行いました。画面が残る場合は手動で閉じてください。";
}

functions.scheduleFallbackClose:
function scheduleFallbackClose(prepared) {
  if (prepared !== preparedSave || !prepared.complete || !prepared.requested ||
      stopRequested || !isOwnedExporter()) return;
  const generation = fallbackCloseGeneration;
  cancelFallbackCloseButton.hidden = false;
  saveStatus.textContent = "ダウンロードを開始しました。5秒後に閉じます（保存完了は未確認）。";
  fallbackCloseTimer = setTimeout(() => {
    if (generation !== fallbackCloseGeneration) return;
    fallbackCloseTimer = null;
    cancelFallbackCloseButton.hidden = true;
    if (prepared === preparedSave && prepared.complete && prepared.requested &&
        !running && !saveBusy && !stopRequested && isOwnedExporter()) {
      closeOwnedExporter();
    }
  }, 5000);
}
